#include "hv_runtime.h"
#include <algorithm>
#include <cstdio>
namespace {
constexpr size_t LIMIT=256, MAX_STONES=24;
const char* shops[]={"arrItemNonNam","arrItemNonNu","arrItemAoNam","arrItemAoNu","arrItemGangTayNam","arrItemGangTayNu","arrItemQuanNam","arrItemQuanNu","arrItemGiayNam","arrItemGiayNu","arrItemGiayChuyen","arrItemNhan","arrItemNgocBoi","arrItemPhu","arrItemWeapon"};
struct State {bool active=false,preview=false;int pending=0,list=0,id=0,slot=0,qty=0;void* item=nullptr;uint64_t deadline=0,next=0,rest=0;int failures=0; } s;
void* tpl(void*i){return hv_obj(i,"ItemGame","template");}int val(void*i,const char*f){return (int)hv_int(i,"ItemGame",f);}int tid(void*i){return (int)hv_int(tpl(i),"ItemGameTemplate","id");}int type(void*i){return (int)hv_int(tpl(i),"ItemGameTemplate","type");}
size_t count(void*a){return std::min(hv_array_count(a),LIMIT);}int free_slots(void*a){int n=0;for(size_t i=0;i<count(a);++i)n+=hv_array_at(a,i)==nullptr;return n;}
bool candidate(void*i){if(!i||!tpl(i)||type(i)<0||type(i)>9)return false;for(auto*f:{"upgrade","isLock","isSelectLuyenDa","isSelect","isExpires"})if(!hv_has_field("ItemGame",f)||val(i,f))return false;if(!hv_obj(i,"ItemGame","options")||!hv_has_method("ItemGame","isHaveGem",0))return false;void*b=hv_call(i,"ItemGame","isHaveGem");return b && hv_unbox_int(b)==0;}
void* list(int n){return hv_obj(nullptr,"ShopItemPopup",shops[n]);}int list_code(int n){return n==14?2:n<10?20+n:16+n-10;}
void* find(int n,int id){void*a=list(n);for(size_t i=0;i<count(a);++i){void*v=hv_array_at(a,i);if(v&&tpl(v)&&tid(v)==id)return v;}return nullptr;}
bool send(const char*m,int argc,void**args,uint64_t now){void*svc=hv_call(nullptr,"Service","gI");if(!svc||!hv_has_method("Service",m,argc))return false;hv_call(svc,"Service",m,argc,args);s.deadline=now+3000;s.next=now+500;return true;}
void finish(uint64_t now){s.active=false;s.preview=false;s.pending=0;s.item=nullptr;s.rest=now+30000;}
// Returns unknown until the actual same-template shop options are loaded.
int shop_lines(void*i,uint64_t now,bool fetch){int t=type(i),lo=t==1?14:t%2?10+(t-3)/2:t,hi=t%2?lo:lo+1;for(int k=lo;k<=hi;k++){if(k<0||k>14)continue;void*a=list(k);void*v=find(k,tid(i));if(v){void*o=hv_obj(v,"ItemGame","options");if(o)return (int)hv_list_count(o);if(fetch){int code=list_code(k),slot=val(v,"indexUI");void*args[]={&code,&slot};s.list=k;s.id=tid(i);s.pending=2;if(!send("requestItemInfo",2,args,now))s.pending=0;}return -1;}if(!a&&fetch){int code=list_code(k);void*args[]={&code};s.list=k;s.pending=1;if(!send("requestItem",1,args,now))s.pending=0;return -1;}}return -1;}
bool transact(void*i,int slot,bool store,uint64_t now){int index=val(i,"indexUI"),qty=val(i,"quantity");if(index<0||index>255||qty<1)return false;void*args[]={&index,&qty};s.item=i;s.slot=slot;s.qty=qty;s.pending=3;return send(store?"itemBagToBox":"sellItem",store?1:2,args,now);}
bool stone(void*ch,void*bag,uint64_t now){void*popup=hv_obj(nullptr,"GameCanvas","currentPop");if(popup && popup==hv_obj(nullptr,"LuyenDaPopupG4M","me"))return false;void*p=hv_obj(nullptr,"ManagerDataGame","crystals"),*fees=hv_obj(nullptr,"ManagerDataGame","coinUpCrystals");int hi=(int)std::min({hv_array_count(p),hv_array_count(fees),size_t(32)})-1;if(hv_cfg.stone_hi>0)hi=std::min(hi,hv_cfg.stone_hi-1);int lo=std::max(0,hv_cfg.stone_lo-1);if(lo>=hi)return false;
for(int target=lo+1;target<=hi;target++){int64_t need=hv_array_int(p,target,4),sum=0,fee=hv_array_int(fees,target,4);if(need<=0||fee<0||fee>hv_int(ch,"Char","yen"))continue;void* chosen[MAX_STONES]{};int slots[MAX_STONES]{},n=0;for(int level=target-1;level>=lo;level--){int64_t weight=hv_array_int(p,level,4);if(weight<=0)continue;for(size_t j=0;j<count(bag)&&n<(int)MAX_STONES;j++){void*i=hv_array_at(bag,j);if(!i||!tpl(i)||type(i)!=26||tid(i)!=level||val(i,"isSelectLuyenDa")||val(i,"quantity")!=1)continue;if(weight<=need-sum){chosen[n]=i;slots[n++]=(int)j;sum+=weight;}}}if(sum!=need||n<2)continue;
void*a=hv_new_array("ItemGame",MAX_STONES);if(!a)return false;for(int k=0;k<n;k++)if(!hv_array_set(a,k,chosen[k]))return false;
// APK185 raw offsets 0x17664fc+0x8c emits cmd19; 0x1766848+0xb4 emits cmd20.
// upPearl VA0x18a3ac0 reads isTypeXu; false branch checks yen+xu then calls Lock.
// Requiring yen>=fee here avoids the server fallback to xu. Initialize response array.
if(!hv_set_obj(nullptr,"LuyenDaPopupG4M","listItemLuyenDa",a))return false;void*args[]={a};s.item=chosen[0];s.slot=slots[0];s.qty=val(chosen[0],"quantity");s.pending=3;return send("crystalCollectLock",1,args,now);}return false;}
}
void hv_bag_reset(){s={};}
bool hv_bag_busy(){return s.active;}
void hv_bag_preview(){if(!s.active){s={};s.active=s.preview=true;}}
void hv_bag_tick(uint64_t now){void*ch=hv_self();void*bag=ch?hv_obj(ch,"Char","listItemBag"):nullptr;if(!bag||hv_array_count(bag)>LIMIT||hv_int(ch,"Char","statusM")==14||hv_int(ch,"Char","statusM")==5){s.active=false;s.preview=false;s.pending=0;s.item=nullptr;return;}if(!s.preview&&(!hv_bool(nullptr,"AutomaticPopupG4M","isAuto")||(!hv_cfg.enabled[HV_SELL]&&!hv_cfg.enabled[HV_STONE]))){s.active=false;s.preview=false;s.pending=0;s.item=nullptr;return;}if(!s.active){if(now<s.rest||free_slots(bag)>1)return;s.active=true;}
if(s.pending){bool done=s.pending==1?list(s.list)!=nullptr:s.pending==2?(find(s.list,s.id)&&hv_obj(find(s.list,s.id),"ItemGame","options")):hv_array_at(bag,s.slot)!=s.item||val(s.item,"quantity")<s.qty;if(!done){if(now<s.deadline)return;s.pending=0;s.active=false;s.preview=false;s.item=nullptr;s.rest=now+300000;return;}s.pending=0;}if(now<s.next)return;
if(s.preview||hv_cfg.enabled[HV_SELL])for(size_t k=0;k<count(bag);k++){void*i=hv_array_at(bag,k);if(!candidate(i))continue;int lines=shop_lines(i,now,true);if(s.pending)return;if(lines<0||s.preview)continue;bool store=(int)hv_list_count(hv_obj(i,"ItemGame","options"))>=lines;void*box=hv_obj(ch,"Char","listItemChest");if(store&&(!box||!free_slots(box)))continue;if(transact(i,(int)k,store,now))return;finish(now);return;}
if(!s.preview&&hv_cfg.enabled[HV_STONE]){if(hv_cfg.stone_hi>0){void*box=hv_obj(ch,"Char","listItemChest");if(box&&free_slots(box))for(size_t k=0;k<count(bag);k++){void*i=hv_array_at(bag,k);if(i&&tpl(i)&&type(i)==26&&tid(i)==hv_cfg.stone_hi-1&&!val(i,"isSelectLuyenDa")&&transact(i,(int)k,true,now))return;}}if(stone(ch,bag,now))return;}finish(now);}
const char*hv_bag_preview_line(size_t index){static char line[256];void*ch=hv_self();void*bag=ch?hv_obj(ch,"Char","listItemBag"):nullptr;for(size_t k=0;k<count(bag);k++){void*i=hv_array_at(bag,k);if(!candidate(i)||index--)continue;int n=(int)hv_list_count(hv_obj(i,"ItemGame","options")),shop=shop_lines(i,0,false);const char*name=hv_utf8(hv_obj(tpl(i),"ItemGameTemplate","name"));std::snprintf(line,sizeof(line),"%.100s: %d/%d -> %s",name?name:"item",n,shop,shop<0?"keep (unknown shop)":n<shop?"sell":"store (if chest space)");return line;}return nullptr;}
